package net.civeira.phylax.feature.observe.observedalert.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.valueobject.SummaryVO;

class SummaryValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of summary of observed alert")
  void test_summary_value_holder_assign_plain_value() {
    Object holder = new Object();
    SummaryValueHolder<Object> value = new SummaryValueHolder<>(holder);
    Assertions.assertSame(holder, value.summary("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getSummaryValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getSummary().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of summary of observed alert")
  void test_summary_value_holder_assign_value_object() {
    Object holder = new Object();
    SummaryValueHolder<Object> value = new SummaryValueHolder<>(holder);
    SummaryVO vo = SummaryVO.from("one");
    Assertions.assertFalse(value.getSummaryValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.summary(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSummaryValue().orElseThrow());
    Assertions.assertSame(holder, value.summary(Optional.empty()));
    Assertions.assertFalse(value.getSummaryValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.summary(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSummaryValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of summary of observed alert against the original")
  void test_summary_value_holder_read() {
    Object holder = new Object();
    SummaryValueHolder<Object> value = new SummaryValueHolder<>(holder);
    SummaryVO vo = SummaryVO.from("one");
    SummaryVO other = SummaryVO.from("one");
    ObservedAlert original = Mockito.mock(ObservedAlert.class);
    Mockito.when(original.getSummaryValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSummary(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readSummary(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.summary(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSummary(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSummary(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of summary of observed alert")
  void test_summary_value_holder_unset() {
    Object holder = new Object();
    SummaryValueHolder<Object> value = new SummaryValueHolder<>(holder);
    SummaryVO vo = SummaryVO.from("one");
    value.summary(vo);
    Assertions.assertSame(holder, value.unsetSummaryIfMatches("summary_other"));
    Assertions.assertTrue(value.getSummaryValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSummaryIfMatches("summary"));
    Assertions.assertFalse(value.getSummaryValue().isPresent(),
        "The field name must clear the value");
    value.summary(vo);
    Assertions.assertSame(holder, value.unsetSummary());
    Assertions.assertFalse(value.getSummaryValue().isPresent(), "Unset must clear the value");
  }
}
